  ('Q74009', 'Invasion of Dominica', 'The Invasion of Dominica was a British military expedition to capture the Caribbean island of Dominica in June 1761, as part of the Seven Years'' War.', 1761, 6, NULL, NULL, NULL, NULL, 'month', 'June 1761', 39, 'https://en.wikipedia.org/wiki/Invasion_of_Dominica_(1761)'),
  ('Q2890526', 'Invasion of Dominica', 'The French invaded the island of Dominica in the British West Indies on 7 September 1778 during the American Revolutionary War. The action took place before British authorities in the Caribbean were aware that France had entered the war as an ally of the United States of America.', 1778, 9, 7, NULL, NULL, NULL, 'day', '7 September 1778', 39, 'https://en.wikipedia.org/wiki/Invasion_of_Dominica_(1778)'),
